abstract class Shape {
    abstract int area();
    int doubled() {
        return area() * 2;
    }
}
class Square extends Shape {
    private final int side;
    Square(int side) {
        this.side = side;
    }
    @Override
    int area() {
        return side * side;
    }
}
public class Main {
    public static void main(String[] args) {
        Shape s = new Square(3);
        System.out.print(s.doubled());
    }
}

