interface Formatter {
    private String wrap(String s) {
        return "[" + s + "]";
    }
    default String label(String s) {
        return wrap(s.toUpperCase());
    }
}
class Item implements Formatter { }

public class Main {
    public static void main(String[] args) {
        Formatter f = new Item();
        System.out.print(f.label("java"));
    }
}

interface Util {
    private static String prefix() {
        return "P";
    }
    static String make(String s) {
        return prefix() + s;
    }
    default String instance(String s) {
        return prefix() + ":" + s;
    }
}
class Impl implements Util { }

public class Main {
    public static void main(String[] args) {
        System.out.print(Util.make("X") + ":");
        System.out.print(new Impl().instance("Y"));
    }
}

record User(String name, int age) {
    User {
        if (age < 0) {
            age = 0;
        }
        name = name.toUpperCase();
    }

    String label() {
        return name + ":" + age;
    }
}
public class Main {
    public static void main(String[] args) {
        User u = new User("amy", -2);
        System.out.print(u.label());
    }
}

